<template>
  <view class="shell">
    <view class="sidebar">
      <view class="brand"><view class="brand-mark">星</view><view><text>星河服务</text><text>{{ roleLabel }}</text></view></view>
      <view class="menu"><view v-for="item in menu" :key="item.key" class="menu-item" :class="{active:active===item.key}" @click="navigate(item.url)"><view class="menu-dot"/><text>{{ item.label }}</text><text v-if="item.badge" class="menu-badge">{{ item.badge }}</text></view></view>
      <view class="sidebar-footer"><view class="user-avatar">{{ userInitial }}</view><view class="user-copy"><text>{{ userName }}</text><text>{{ maskedPhone }}</text></view><button class="logout-button" @click="doLogout">退出</button></view>
    </view>
    <view class="workspace">
      <view class="topbar"><view><text class="mobile-brand">星河服务</text><text class="breadcrumb">{{ roleLabel }} / {{ title }}</text></view><view class="topbar-tools"><text class="environment">本地演示</text><text class="clock">{{ today }}</text></view></view>
      <scroll-view scroll-y class="content-scroll"><view class="content"><view class="page-heading"><view><text class="page-title">{{ title }}</text><text v-if="subtitle" class="page-subtitle">{{ subtitle }}</text></view><slot name="actions"/></view><slot/></view></scroll-view>
      <view class="mobile-nav"><view v-for="item in menu" :key="item.key" :class="{active:active===item.key}" @click="navigate(item.url)"><view class="mobile-icon"/><text>{{ item.short||item.label }}</text></view></view>
    </view>
  </view>
</template>

<script setup>
import { computed } from 'vue'; import { go,logout } from '../common.js'; import { maskPhone } from '../utils/display.js';
const props=defineProps({role:{type:String,default:'worker'},active:{type:String,required:true},title:{type:String,required:true},subtitle:{type:String,default:''}});
const csMenu=[{key:'dashboard',label:'工作台',url:'/pages/cs/workbench'},{key:'orders',label:'订单管理',short:'订单',url:'/pages/cs/orders'},{key:'pool',label:'抢单池',url:'/pages/cs/pool'},{key:'approvals',label:'审批中心',short:'审批',url:'/pages/cs/approvals'},{key:'security',label:'安全中心',short:'安全',url:'/pages/security/index'}];
const workerMenu=[{key:'pool',label:'订单池',url:'/pages/worker/hall'},{key:'orders',label:'我的订单',short:'订单',url:'/pages/worker/orders'},{key:'wallet',label:'我的钱包',short:'钱包',url:'/pages/worker/wallet'},{key:'profile',label:'个人资料',short:'资料',url:'/pages/worker/profile'}];
const menu=computed(()=>props.role==='cs'?csMenu:workerMenu);const roleLabel=computed(()=>props.role==='cs'?'客服工作台':'接单工作台');
const user=computed(()=>{try{return uni.getStorageSync('user')||{};}catch(e){return {};}});const userName=computed(()=>user.value.nickname||(props.role==='cs'?'客服人员':'接单人员'));const userInitial=computed(()=>userName.value.slice(0,1));const maskedPhone=computed(()=>maskPhone(user.value.phone)||'已登录');const today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'});
function navigate(url){go(url);}function doLogout(){logout();}
</script>

